import { fraction } from '../../features/unit-v2/math/fraction.ts'
import type { ChallengeItem, DiagnosticQuestion, ExerciseSection, LocalizedText, PracticeItem } from '../../features/unit-v2/types.ts'
import { same, say } from '../batx1-zientziak-funtzioak/text.ts'

/* ==========================================================================
   Deribatuaren aplikazioak · Batxilergoa 2 · Zientziak — diagnostic,
   guided practice, exercise bank and challenges, with the scope of unit 9
   of Santillana 2.º Bachillerato Ciencias and unit 9 of Anaya Matemáticas
   II (all the exercises and numbers are our own; the coefficients from an
   extremum, an inflection or a tangent and the optimisation problems
   follow the style of the Basque EBAU). Every closed answer is a single
   number: an abscissa, a value, a coefficient (or a sum of them), how
   many roots or extrema there are, a limit or its logarithm, or the
   optimum of a problem.
   ========================================================================== */

const n = (value: number) => fraction(value)
const f = (numerator: number, denominator: number) => fraction(numerator, denominator)

const limit = (expression: string) => say(`Kalkulatu $${expression}$.`, `Calcula $${expression}$.`, `احسب $${expression}$.`, `Work out $${expression}$.`)
const howMuch = (statement: LocalizedText, letter: string) => say(`${statement.eu} Zenbat da $${letter}$?`, `${statement.es} ¿Cuánto vale $${letter}$?`, `${statement.ar} كم تساوي $${letter}$؟`, `${statement.en} What is $${letter}$?`)
/** «How many real roots does … = 0 have?» */
const roots = (equation: string) => say(`Zenbat erro erreal ditu $${equation}$ ekuazioak?`, `¿Cuántas raíces reales tiene $${equation}$?`, `كم جذرًا حقيقيًّا للمعادلة $${equation}$؟`, `How many real roots does $${equation}$ have?`)
/** «Find the c of Rolle / of the mean value for f on [a, b]» */
const rolleC = (fn: string, interval: string) => say(`Aurkitu $f(x)=${fn}$ funtzioaren Rolleren $c$ puntua $${interval}$ tartean.`, `Halla el $c$ de Rolle de $f(x)=${fn}$ en $${interval}$.`, `أوجد $c$ لمبرهنة رول للدالة $f(x)=${fn}$ على $${interval}$.`, `Find the Rolle point $c$ of $f(x)=${fn}$ on $${interval}$.`)
const meanC = (fn: string, interval: string) => say(`Aurkitu batez besteko balioaren $c$, $f(x)=${fn}$ funtziorako $${interval}$ tartean.`, `Halla el $c$ del valor medio de $f(x)=${fn}$ en $${interval}$.`, `أوجد $c$ في مبرهنة القيمة المتوسطة للدالة $f(x)=${fn}$ على $${interval}$.`, `Find the mean value $c$ of $f(x)=${fn}$ on $${interval}$.`)
/** «The absolute maximum / minimum of f on [a, b]» */
const absolute = (kind: 'max' | 'min', fn: string, interval: string) => kind === 'max'
    ? say(`Zein da $f(x)=${fn}$ funtzioaren maximo absolutua $${interval}$ tartean?`, `¿Cuál es el máximo absoluto de $f(x)=${fn}$ en $${interval}$?`, `ما القيمة العظمى المطلقة للدالة $f(x)=${fn}$ على $${interval}$؟`, `What is the absolute maximum of $f(x)=${fn}$ on $${interval}$?`)
    : say(`Zein da $f(x)=${fn}$ funtzioaren minimo absolutua $${interval}$ tartean?`, `¿Cuál es el mínimo absoluto de $f(x)=${fn}$ en $${interval}$?`, `ما القيمة الصغرى المطلقة للدالة $f(x)=${fn}$ على $${interval}$؟`, `What is the absolute minimum of $f(x)=${fn}$ on $${interval}$?`)
/** «f(x) = … has an extremum / an inflection / a minimum at …» */
const hasExtremum = (fn: string, where: string) => say(`$f(x)=${fn}$ funtzioak mutur bat du $${where}$ puntuan.`, `$f(x)=${fn}$ tiene un extremo en $${where}$.`, `للدالة $f(x)=${fn}$ قيمة قصوى عند $${where}$.`, `$f(x)=${fn}$ has an extremum at $${where}$.`)
const hasInflection = (fn: string, where: string) => say(`$f(x)=${fn}$ funtzioak inflexio bat du $${where}$ puntuan.`, `$f(x)=${fn}$ tiene una inflexión en $${where}$.`, `للدالة $f(x)=${fn}$ نقطة انعطاف عند $${where}$.`, `$f(x)=${fn}$ has an inflection at $${where}$.`)
const hasMinimum = (fn: string, where: string) => say(`$f(x)=${fn}$ funtzioak minimo bat du $${where}$ puntuan.`, `$f(x)=${fn}$ tiene un mínimo en $${where}$.`, `للدالة $f(x)=${fn}$ قيمة صغرى عند $${where}$.`, `$f(x)=${fn}$ has a minimum at $${where}$.`)
const hasMaximum = (fn: string, where: string) => say(`$f(x)=${fn}$ funtzioak maximo bat du $${where}$ puntuan.`, `$f(x)=${fn}$ tiene un máximo en $${where}$.`, `للدالة $f(x)=${fn}$ قيمة عظمى عند $${where}$.`, `$f(x)=${fn}$ has a maximum at $${where}$.`)
/** «The tangent to f at x = a is …» */
const tangentIs = (fn: string, point: string, line: string) => say(`$f(x)=${fn}$ funtzioaren zuzen ukitzailea $x=${point}$ puntuan $${line}$ da.`, `La tangente a $f(x)=${fn}$ en $x=${point}$ es $${line}$.`, `مماس $f(x)=${fn}$ عند $x=${point}$ هو $${line}$.`, `The tangent to $f(x)=${fn}$ at $x=${point}$ is $${line}$.`)
/** «If L = lim …, what is ln L?» */
const logOf = (expression: string) => say(`$L=${expression}$ bada, zenbat da $\\ln L$?`, `Si $L=${expression}$, ¿cuánto vale $\\ln L$?`, `إذا كانت $L=${expression}$ فكم تساوي $\\ln L$؟`, `If $L=${expression}$, what is $\\ln L$?`)
/** «At which abscissa does f have its …?» */
const abscissa = (kind: 'max' | 'min' | 'inflection', fn: string) => ({
    max: say(`Zein abzisatan du $f(x)=${fn}$ funtzioak maximo erlatiboa?`, `¿En qué abscisa tiene $f(x)=${fn}$ su máximo relativo?`, `عند أي فاصلة تبلغ $f(x)=${fn}$ قيمتها العظمى المحلية؟`, `At which abscissa does $f(x)=${fn}$ have its local maximum?`),
    min: say(`Zein abzisatan du $f(x)=${fn}$ funtzioak minimo erlatiboa?`, `¿En qué abscisa tiene $f(x)=${fn}$ su mínimo relativo?`, `عند أي فاصلة تبلغ $f(x)=${fn}$ قيمتها الصغرى المحلية؟`, `At which abscissa does $f(x)=${fn}$ have its local minimum?`),
    inflection: say(`Zein abzisatan du $f(x)=${fn}$ funtzioak inflexio-puntua?`, `¿En qué abscisa tiene $f(x)=${fn}$ su punto de inflexión?`, `عند أي فاصلة تكون نقطة انعطاف $f(x)=${fn}$؟`, `At which abscissa does $f(x)=${fn}$ have its point of inflection?`)
})[kind]

